INSERT INTO _migration_620_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_bece_intsci_s3_008', 'topic_bece_science_body', 'subj_bece_science', 'exam_bece', NULL, NULL, 'State two functions of the human skeleton other than giving the body its shape.', 'short_answer', NULL, NULL, 'Any two of: it protects delicate organs such as the brain, heart and lungs; it allows movement by providing attachment for muscles; it makes blood cells in the bone marrow; it stores minerals such as calcium.', 'Besides supporting and shaping the body, the skeleton protects delicate organs (the skull guards the brain and the ribs guard the heart and lungs), provides firm attachment points for muscles so that movement is possible, manufactures red and white blood cells in the bone marrow, and stores minerals such as calcium and phosphorus. Any two of these functions earn the marks.', 'medium', '2', '2', '90', NULL, NULL, '1', NULL, NULL, 'State', 'AO1', NULL, NULL, 'board_waec'),
('q_bece_intsci_s3_009', 'topic_bece_science_body', 'subj_bece_science', 'exam_bece', NULL, NULL, 'After exercising, Esi counts her pulse 21 times in 15 seconds. Calculate her heart rate in beats per minute.', 'calculation', NULL, NULL, '84 beats per minute', 'There are 4 × 15 = 60 seconds in one minute, so multiply the 15-second count by 4: 21 × 4 = 84. Answer: her heart rate is 84 beats per minute.', 'easy', '4', '2', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, 'board_waec'),
('q_bece_intsci_s3_010', 'topic_bece_science_body', 'subj_bece_science', 'exam_bece', NULL, NULL, 'Yaw is learning about how the human digestive system deals with a meal of kenkey and fish.', 'structured', NULL, NULL, '(a) Digestion is the breakdown of large, insoluble food molecules into small, soluble molecules that can be absorbed into the blood (1). (b) (i) The mouth, where the enzyme amylase in saliva starts to break down starch (1). (ii) The small intestine (ileum) (1). (c) Its inner surface is folded into many tiny finger-like villi, which give a very large surface area for absorption (1); each villus has thin walls and a rich blood supply, so digested food passes quickly into the blood (1).', '(a) Digestion is the breakdown of large, insoluble food molecules into small, soluble molecules that can be absorbed into the blood (1). (b) (i) The mouth, where the enzyme amylase in saliva starts to break down starch (1). (ii) The small intestine (ileum) (1). (c) Its inner surface is folded into many tiny finger-like villi, which give a very large surface area for absorption (1); each villus has thin walls and a rich blood supply, so digested food passes quickly into the blood (1).', 'medium', '5', '5', NULL, NULL, NULL, '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, 'board_waec'),
('q_bece_intsci_s3_011', 'topic_bece_science_matter', 'subj_bece_science', 'exam_bece', NULL, NULL, 'When 50 cm³ of water is mixed with 50 cm³ of ethanol, the final volume is slightly less than 100 cm³. What does this show about matter?', 'multiple_choice', NULL, '["A. Particles of matter have spaces between them, so smaller particles fill gaps between larger ones","B. Some of the liquid always evaporates during mixing","C. The two liquids react to form a solid","D. Matter is destroyed when liquids are mixed"]', 'A', 'The particle theory says matter is made of tiny particles with spaces between them. When water and ethanol mix, some of the smaller particles occupy spaces between the larger ones, so the total volume shrinks slightly. (No measurable evaporation or chemical reaction takes place during the mixing, and matter cannot be destroyed by simply mixing liquids.) Therefore the correct answer is A: Particles of matter have spaces between them, so smaller particles fill gaps between larger ones.', 'hard', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO3', NULL, NULL, 'board_waec'),
('q_bece_intsci_s3_012', 'topic_bece_science_matter', 'subj_bece_science', 'exam_bece', NULL, NULL, 'A mixture contains iron filings, sand and common salt. A learner wants a sample of pure salt. Which sequence of separation methods is correct?', 'multiple_choice', NULL, '["A. Evaporate first, then filter, then use a magnet","B. Use a magnet, dissolve the rest in water and filter, then evaporate the filtrate","C. Filter the dry mixture, then dissolve and evaporate","D. Dissolve everything, filter, then use a magnet on the solution"]', 'B', 'A magnet first pulls out the magnetic iron filings. Adding water then dissolves only the salt; filtering removes the insoluble sand as the residue. Evaporating (or crystallising) the filtrate finally recovers the dissolved salt. (A dry mixture of solids cannot be filtered, and the magnet must be used before dissolving or the filings end up in the filter paper.) Therefore the correct answer is B: Use a magnet, dissolve the rest in water and filter, then evaporate the filtrate.', 'hard', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Sequence', 'AO3', NULL, NULL, 'board_waec'),
('q_bece_intsci_s3_013', 'topic_bece_science_matter', 'subj_bece_science', 'exam_bece', NULL, NULL, 'State two differences between a mixture and a compound.', 'short_answer', NULL, NULL, 'In a mixture the substances keep their own properties and can be separated by physical methods; in a compound the elements are chemically combined in a fixed ratio and can be separated only by chemical means.', 'A mixture contains two or more substances that are not chemically joined: each keeps its own properties, the amounts can vary, and the substances can be separated by physical methods such as filtering or evaporation. A compound forms when elements chemically combine in a fixed ratio; it has completely new properties and can be split up only by chemical means. Any two of these differences earn the marks.', 'medium', '2', '2', '90', NULL, NULL, '1', NULL, NULL, 'State', 'AO1', NULL, NULL, 'board_waec'),
('q_bece_intsci_s3_014', 'topic_bece_science_matter', 'subj_bece_science', 'exam_bece', NULL, NULL, 'A stone has a mass of 54 g. When it is fully immersed, it raises the level of water in a measuring cylinder from 50 cm³ to 70 cm³. Calculate the density of the stone.', 'calculation', NULL, NULL, '2.7 g/cm³', 'Volume of the stone = 70 cm³ − 50 cm³ = 20 cm³. Density = mass ÷ volume = 54 g ÷ 20 cm³ = 2.7 g/cm³. Answer: the density of the stone is 2.7 g/cm³.', 'medium', '4', '2', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, 'board_waec');
INSERT INTO _migration_620_expected_parts (id, question_id, part_label, part_text, marks, correct_answer, display_order) VALUES ('sqp_q_bece_intsci_s3_010_a', 'q_bece_intsci_s3_010', 'a', 'Define digestion.', '1', 'Digestion is the breakdown of large, insoluble food molecules into small, soluble molecules that can be absorbed into the blood (1).', '1'),
('sqp_q_bece_intsci_s3_010_b', 'q_bece_intsci_s3_010', 'b', 'State the part of the digestive system where (i) digestion of starch begins and (ii) most absorption of digested food takes place.', '2', '(i) The mouth, where the enzyme amylase in saliva starts to break down starch (1). (ii) The small intestine (ileum) (1).', '2'),
('sqp_q_bece_intsci_s3_010_c', 'q_bece_intsci_s3_010', 'c', 'Explain how the small intestine is adapted for absorbing digested food.', '2', 'Its inner surface is folded into many tiny finger-like villi, which give a very large surface area for absorption (1); each villus has thin walls and a rich blood supply, so digested food passes quickly into the blood (1).', '3');
INSERT INTO _migration_620_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_620_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_620_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'bece-int-science-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned BECE Integrated Science practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/common-core-programme-ccp/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM _migration_620_expected_parts p JOIN structured_question_parts sp ON sp.id = p.id WHERE NOT (sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_620_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) SELECT p.id, p.question_id, p.part_label, p.part_text, p.marks, p.correct_answer, NULL, 'text', p.display_order FROM _migration_620_expected_parts p WHERE NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = p.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'bece-int-science-sprint3-001', 'automated_beta', 'beta', 'Original BrillaPrep curriculum-aligned BECE Integrated Science practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.', 'https://nacca.gov.gh/common-core-programme-ccp/', 0, 1 FROM _migration_620_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
INSERT INTO _migration_620_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_620_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 7 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_620_expected e ON e.id = r.question_id WHERE r.batch_id IS 'bece-int-science-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned BECE Integrated Science practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/common-core-programme-ccp/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 7 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_620_expected e ON e.id = q.id) = 7 AND (SELECT COUNT(*) FROM structured_question_parts sp JOIN _migration_620_expected_parts p ON p.id = sp.id AND sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order) = 3 THEN 1 ELSE 0 END;
